  2422  /**
  2423   * Convert a decimal (e.g. 3.5) to a fraction (e.g. 7/2).
  2424   * From: https://www.designedbyaturtle.co.uk/2015/converting-a-decimal-to-a-fraction-in-php/
  2425   *
  2426   * @param float $decimal the decimal number.
  2427   * @return array|bool a 1/2 would be [1, 2] array (this can be imploded with '/' to form a string).
  2428   */
  2429  function wc_decimal_to_fraction( $decimal ) {
  2430  	if ( 0 > $decimal || ! is_numeric( $decimal ) ) {
  2431  		// Negative digits need to be passed in as positive numbers and prefixed as negative once the response is imploded.
  2432  		return false;
  2433  	}
  2434  
  2435  	if ( 0 === $decimal ) {
  2436  		return array( 0, 1 );
  2437  	}
  2438  
  2439  	$tolerance   = 1.e-4;
  2440  	$numerator   = 1;
  2441  	$h2          = 0;
  2442  	$denominator = 0;
  2443  	$k2          = 1;
  2444  	$b           = 1 / $decimal;
  2445  
  2446  	do {
  2447  		$b           = 1 / $b;
  2448  		$a           = floor( $b );
  2449  		$aux         = $numerator;
  2450  		$numerator   = $a * $numerator + $h2;
  2451  		$h2          = $aux;
  2452  		$aux         = $denominator;
  2453  		$denominator = $a * $denominator + $k2;
  2454  		$k2          = $aux;
  2455  		$b           = $b - $a;
  2456  	} while ( abs( $decimal - $numerator / $denominator ) > $decimal * $tolerance );
  2457  
  2458  	return array( $numerator, $denominator );
  2459  }
